def match(orders):
    trades = []
    buy_book = []  # List of (price, arrival_time, id, qty)
    sell_book = []  # List of (price, arrival_time, id, qty)
    order_map = {}  # id -> (side, price, qty, arrival_time, cancelled)
    arrival_counter = [0]  # Use list to make it mutable in nested function

    def add_order_to_book(side, id, price, qty, arrival_time):
        if side == 'buy':
            buy_book.append((price, arrival_time, id, qty))
            buy_book.sort(key=lambda x: (-x[0], x[1]))  # Sort by price desc, then arrival asc
        else:
            sell_book.append((price, arrival_time, id, qty))
            sell_book.sort(key=lambda x: (x[0], x[1]))  # Sort by price asc, then arrival asc

    def find_order_in_book(side, id):
        book = buy_book if side == 'buy' else sell_book
        for i, (price, arrival_time, order_id, qty) in enumerate(book):
            if order_id == id:
                return i
        return -1

    def match_order(side, price, qty, id, is_market):
        nonlocal trades, buy_book, sell_book

        if side == 'buy':
            # Match against sell_book
            while qty > 0 and sell_book:
                if not is_market and sell_book[0][0] > price:
                    break  # Can't match at this price

                sell_price, sell_arrival, sell_id, sell_qty = sell_book[0]

                if sell_price > price and not is_market:
                    break

                trade_qty = min(qty, sell_qty)
                trades.append([id, sell_id, sell_price, trade_qty])

                qty -= trade_qty
                sell_book[0] = (sell_price, sell_arrival, sell_id, sell_qty - trade_qty)

                if sell_book[0][3] == 0:
                    sell_book.pop(0)
        else:
            # Match against buy_book
            while qty > 0 and buy_book:
                if not is_market and buy_book[0][0] < price:
                    break  # Can't match at this price

                buy_price, buy_arrival, buy_id, buy_qty = buy_book[0]

                if buy_price < price and not is_market:
                    break

                trade_qty = min(qty, buy_qty)
                trades.append([buy_id, id, buy_price, trade_qty])

                qty -= trade_qty
                buy_book[0] = (buy_price, buy_arrival, buy_id, buy_qty - trade_qty)

                if buy_book[0][3] == 0:
                    buy_book.pop(0)

        return qty

    for order in orders:
        if order[0] == 'limit':
            _, id, side, price, qty = order
            arrival_time = arrival_counter[0]
            arrival_counter[0] += 1

            remaining_qty = match_order(side, price, qty, id, False)

            if remaining_qty > 0:
                add_order_to_book(side, id, price, remaining_qty, arrival_time)
                order_map[id] = (side, price, remaining_qty, arrival_time, False)
            else:
                order_map[id] = (side, price, 0, arrival_time, False)

        elif order[0] == 'ioc':
            _, id, side, price, qty = order
            arrival_time = arrival_counter[0]
            arrival_counter[0] += 1

            remaining_qty = match_order(side, price, qty, id, False)
            order_map[id] = (side, price, 0, arrival_time, False)  # IOC doesn't rest

        elif order[0] == 'market':
            _, id, side, qty = order
            arrival_time = arrival_counter[0]
            arrival_counter[0] += 1

            remaining_qty = match_order(side, 0, qty, id, True)
            order_map[id] = (side, 0, 0, arrival_time, False)  # Market doesn't rest

        elif order[0] == 'cancel':
            _, id = order

            if id not in order_map:
                continue

            side, price, qty, arrival_time, _ = order_map[id]

            idx = find_order_in_book(side, id)
            if idx >= 0:
                book = buy_book if side == 'buy' else sell_book
                book.pop(idx)
                order_map[id] = (side, price, 0, arrival_time, True)

    return trades

